def transform(grid):
    h, w = len(grid), len(grid[0])
    mid_r, mid_c = h // 2, w // 2
    rows = []
    for r, row in enumerate(grid):
        expanded = []
        for c, value in enumerate(row):
            expanded.append(value)
            if r != mid_r and c != mid_c:
                expanded.append(value)
        rows.append(expanded)
        if r != mid_r:
            rows.append(expanded[:])
    return rows
